<script setup>
import { computed } from 'vue';
import { Head, useForm } from '@inertiajs/vue3';
import AdminLayout from '../../../Layouts/AdminLayout.vue';
import DataPanel from '../../../Components/Ui/DataPanel.vue';
import PageHeader from '../../../Components/Ui/PageHeader.vue';
defineOptions({layout:AdminLayout});
const props=defineProps({unit:{type:Object,required:true},types:{type:Array,required:true},urls:{type:Object,required:true}});
const editing=computed(()=>Boolean(props.unit.id));const form=useForm({code:props.unit.code,name:props.unit.name,unit_type:props.unit.type,factor_to_base:props.unit.factor,is_base:props.unit.base});
const selected=computed(()=>props.types.find(x=>x.value===form.unit_type));
function submit(){editing.value?form.put(props.urls.submit):form.post(props.urls.submit)}
</script>
<template>
<Head :title="editing?'تعديل وحدة':'وحدة جديدة'"/><PageHeader :title="editing?`تعديل ${unit.name}`:'وحدة قياس جديدة'" icon="bi-rulers" :subtitle="editing&&unit.used?'الوحدة مستخدمة؛ غيّر الاسم بحذر ولا تغيّر معناها أو معاملها.':'عرّف معنى الوحدة ومعاملها مرة واحدة'" :crumbs="[{label:'وحدات القياس',url:urls.index}]"/>
<div v-if="editing&&unit.used" class="warning"><i class="bi bi-exclamation-triangle-fill"></i><span><strong>هذه الوحدة مستخدمة في بيانات سابقة</strong><small>تغيير المعامل يغيّر معنى العرض في كل مكان. إن احتجت معنى جديداً، أنشئ وحدة جديدة.</small></span></div>
<form @submit.prevent="submit"><DataPanel title="تعريف الوحدة" icon="bi-sliders2"><div class="type-cards"><button v-for="type in types" :key="type.value" type="button" :class="{active:form.unit_type===type.value}" @click="form.unit_type=type.value"><i class="bi" :class="{weight:'bi-speedometer',volume:'bi-droplet-fill',count:'bi-123',length:'bi-rulers'}[type.value]"></i><span><strong>{{type.label}}</strong><small>أساسه المعتاد: {{type.baseExample}}</small></span><i class="bi" :class="form.unit_type===type.value?'bi-check-circle-fill':'bi-circle'"></i></button></div><div class="unit-fields"><label><span>الرمز *</span><input v-model="form.code" class="form-control" maxlength="16" required placeholder="kg"><small v-if="form.errors.code">{{form.errors.code}}</small></label><label><span>الاسم *</span><input v-model="form.name" class="form-control" required placeholder="كيلوغرام"></label><label><span>معامل التحويل *</span><input v-model="form.factor_to_base" type="number" step="0.0000001" min="0.0000001" class="form-control" required><small>{{selected?.example}}</small></label></div><button type="button" class="base-toggle" :class="{active:form.is_base}" @click="form.is_base=!form.is_base"><i class="bi" :class="form.is_base?'bi-check-circle-fill':'bi-circle'"></i><span><strong>وحدة أساسية لهذا النوع</strong><small>الوحدة الأساسية معاملها عادة 1، مثل غرام أو ملليلتر أو قطعة.</small></span></button></DataPanel><div class="save-bar"><a :href="urls.index" class="btn btn-light">إلغاء</a><span></span><button class="btn btn-primary" :disabled="form.processing"><i class="bi bi-check2"></i> حفظ الوحدة</button></div></form>
</template>
<style scoped>
