@media(max-width:800px){.type-cards{grid-template-columns:1fr 1fr}.unit-fields{grid-template-columns:1fr 1fr}}
@media(max-width:500px){.type-cards,.unit-fields{grid-template-columns:1fr}.save-bar .btn-primary{flex:1}}
</style>
